mapper.select:
WITH k (supplier_id, material_id, sku_id, unit) AS ( VALUES
(#{x.supplierId}::bigint, #{x.materialId}::bigint, #{x.materialSkuId,jdbcType=BIGINT}::bigint, #{x.unit}::varchar)
) SELECT DISTINCT ON (k.supplier_id, k.material_id, k.sku_id) k.sku_id AS key_sku_id, p.* FROM k JOIN prc_price p ON p.type = 'MATERIAL' AND p.supplier_id = k.supplier_id AND p.material_id = k.material_id AND p.unit = k.unit AND NOT p.voided AND p.effective_date <= #{date} AND (p.material_sku_id = k.sku_id OR p.material_sku_id IS NULL) ORDER BY k.supplier_id, k.material_id, k.sku_id, p.material_sku_id IS NULL, p.effective_date DESC, p.id DESC

SELECT p.*
FROM prc_price p
WHERE p.type = 'PROCESS' AND p.supplier_id = #{supplierId} AND p.style_id = #{styleId}
  AND p.process_mode = #{processMode} AND NOT p.voided AND p.effective_date <= #{date}
ORDER BY p.effective_date DESC, p.id DESC
LIMIT 1
